function setupUpdates(){let el=$('#update-status');if(!el||!window.desktop?.onUpdate)return;window.desktop.version().then(v=>{el.textContent=`V${v} · VERIFICAR`;el.title='O jogo procura atualizações automaticamente'});window.desktop.onUpdate(({status,detail})=>{el.className='update-status';el.onclick=null;if(status==='checking')el.textContent='VERIFICANDO...';if(status==='downloading')el.textContent=`BAIXANDO V${detail}`;if(status==='progress')el.textContent=`ATUALIZANDO ${detail}%`;if(status==='current')el.textContent=`V${detail} · ATUAL`;if(status==='ready'){el.textContent=`V${detail} PRONTA · REINICIAR`;el.classList.add('ready');el.onclick=()=>{save();window.desktop.installUpdate()}}if(status==='error'){el.textContent='UPDATE INDISPONÍVEL';el.classList.add('error');el.title=detail}})}
function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);draw();renderTop();autosave+=dt;if(autosave>10&&!window.__visualTestActive){save();autosave=0}requestAnimationFrame(loop)}applyOfflineFarm();startWave();renderPanel();renderAbilities();requestAnimationFrame(loop);window.addEventListener('beforeunload',()=>{if(!window.__visualTestActive)save()});
function bindSaveCenter(){document.addEventListener('click',async event=>{let b=event.target.closest('[data-export-save],[data-import-save],[data-save-name]');if(!b)return;if(b.hasAttribute('data-save-name')){S.playerName=($('#save-player-name')?.value||'Sobrevivente').trim().slice(0,24)||'Sobrevivente';save();toast('Nome do save atualizado');renderPanel('archive')}else if(b.hasAttribute('data-export-save')){try{save();let path=await window.desktop?.exportSave(SaveSystem.encode(S));if(path)toast('Save exportado — envie esse arquivo ao seu amigo')}catch(e){toast('Não foi possível exportar: '+e.message)}}else if(b.hasAttribute('data-import-save')){try{let text=await window.desktop?.importSave();if(!text)return;let imported=SaveSystem.decode(text);if(!confirm(`Importar o save de ${imported.summary.player}?\nMapa ${imported.summary.map}-${imported.summary.level} · ${imported.summary.items} itens\n\nSeu progresso atual ficará em backup.`))return;save();localStorage.setItem('deadshift-save-backup',localStorage.getItem('deadshift-save')||'');localStorage.setItem('deadshift-save',JSON.stringify(hydrate(imported.state)));location.reload()}catch(e){toast('Save recusado: '+e.message)}}})}
function bindGearAssistant(){document.addEventListener('click',event=>{let b=event.target.closest('[data-equip-best],[data-equip-best-all]');if(!b)return;let hero=S.selectedHero,claimed=new Set(Object.entries(S.equipped).filter(([id])=>id!==hero).flatMap(([,set])=>Object.values(set).filter(Boolean))),available=S.inventory.filter(i=>!claimed.has(i.id)),best=RecommendationSystem.bestLoadout(available,hero);if(b.dataset.equipBest){let item=best[b.dataset.equipBest];if(item){S.equipped[hero][item.slot]=item.id;toast(`${item.name} equipado como melhor opção`)}}else{let count=0;for(const [slot,item]of Object.entries(best))if(item){S.equipped[hero][slot]=item.id;count++}toast(`${count} melhores itens equipados automaticamente`)}save();renderPanel('arsenal')})}
