function enhanceCube(){let grid=document.querySelector('.cube-grid');if(!grid)return;S.cube.profile=S.cube.profile||'general';if(!document.querySelector('.cube-options'))grid.insertAdjacentHTML('beforebegin',`<div class="cube-options"><b>FABRICAR PARA:</b>${[['general','GERAL'],['maya','⚡ MAYA'],['bruno','🛡 BRUNO'],['healer','✚ YURI'],['iris','🔥 IRIS']].map(([id,name])=>`<button data-cube-profile="${id}" class="${S.cube.profile===id?'on':''}">${name}</button>`).join('')}</div>`);if(S.cube.lastCraft&&!document.querySelector('.cube-result')){let i=S.cube.lastCraft;grid.insertAdjacentHTML('beforebegin',`<div class="cube-result"><i class="${i.rarity}">${i.icon}</i><span><small>ITEM GERADO · ${i.archetypeLabel||'GERAL'}</small><b class="${i.rarity}">${i.name}</b><small>${statText(i)} · ${i.rarityLabel}</small></span><strong>${i.power}<small>PODER</small></strong></div>`)}}
function quickCandidates(hero){let claimed=new Set(Object.entries(S.equipped).filter(([id])=>id!==hero.id).flatMap(([,set])=>Object.values(set).filter(Boolean)));return S.inventory.filter(i=>!claimed.has(i.id))}
function showQuickGear(heroId){let hero=heroes.find(h=>h.id===heroId);if(!hero||!S.unlocked.includes(heroId))return;let box=$('#quick-gear'),items=quickCandidates(hero),best=RecommendationSystem.bestLoadout(items,hero.id),slotNames={weapon:'ARMA',armor:'PROTEÇÃO',charm:'AMULETO'},slotHtml=slot=>{let current=S.inventory.find(i=>i.id===S.equipped[hero.id][slot]),ranked=RecommendationSystem.rank(items,hero.id,slot).slice(0,4);return`<section class="quick-slot"><header><b>${slotNames[slot]}</b><small>ATUAL: ${current?.name||'VAZIO'}</small></header>${ranked.length?ranked.map(({item},index)=>{let c=RecommendationSystem.compare(item,current,hero.id),equipped=current?.id===item.id;return`<button class="quick-choice ${index===0?'best':''}" data-quick-equip="${hero.id}:${item.id}"><i class="${item.rarity}">${item.icon}</i><span><b class="${item.rarity}">${item.name}</b><small>${index===0?'★ MELHOR SUGESTÃO · ':''}${statText(item)}</small></span><strong>${equipped?'EQUIPADO':(c.percent>0?'+':'')+c.percent+'%'}</strong></button>`}).join(''):'<small>Nenhum item disponível</small>'}</section>`};box.innerHTML=`<div class="quick-modal"><header class="quick-head"><div><i>${hero.icon}</i><span><h2>${hero.name}</h2><small>${hero.role} · escolha ou equipe as melhores sugestões</small></span></div><button data-close-quick>FECHAR ×</button></header><div class="quick-slots">${slotHtml('weapon')}${slotHtml('armor')}${slotHtml('charm')}</div><button class="quick-all" data-quick-best-all="${hero.id}">★ EQUIPAR MELHOR CONJUNTO PARA ${hero.name.toUpperCase()}</button></div>`;box.classList.add('show')}
function craftCube(slot){let cost=CubeSystem.craftCost(S,slot);if(S.scrap<cost)return;S.scrap-=cost;let profile=S.cube.profile==='general'?undefined:S.cube.profile,item;do item=LootSystem.generate({level:CampaignSystem.absolute(S),pity:S.cube.level/5,profile});while(item.slot!==slot);S.inventory.unshift(item);S.inventory=S.inventory.slice(0,60);S.cube.lastCraft=item;CubeSystem.gain(S,20+item.power*.025);save();toast(`GERADO: ${item.name} · ${item.power} poder`);renderPanel('cube')}
function synthCube(){let equipped=Object.values(S.equipped).flatMap(x=>Object.values(x)),group=CubeSystem.synthesisGroup(S.inventory,equipped);if(group.length<9)return;let rarity=CubeSystem.nextRarity(group[0].rarity),profile=S.cube.profile==='general'?undefined:S.cube.profile,item=LootSystem.generate({level:CampaignSystem.absolute(S),pity:rarity==='legendary'?15:8,boss:['epic','legendary'].includes(rarity),profile}),mult=rarity==='legendary'?1.45:1.25;item.rarity=rarity;item.rarityLabel=LootSystem.RARITIES[rarity].label;for(const key of Object.keys(item.stats))item.stats[key]=typeof item.stats[key]==='number'?+(item.stats[key]*mult).toFixed(3):item.stats[key];item.power=Math.round(item.power*mult);S.inventory=S.inventory.filter(i=>!group.includes(i));S.inventory.unshift(item);S.cube.lastCraft=item;CubeSystem.gain(S,group.reduce((n,i)=>n+Math.max(2,i.power*.04),0)*(1+(RuneSystem.bonuses(S).cube||0)));save();toast(`SÍNTESE GERADA: ${item.name}`);renderPanel('cube')}
